package com.orderflow.notification.service;import com.orderflow.events.*;import com.orderflow.notification.config.KafkaTopicProperties;import com.orderflow.notification.domain.*;import com.orderflow.notification.outbox.OutboxStore;import com.orderflow.notification.provider.*;import com.orderflow.notification.repository.*;import io.micrometer.core.instrument.MeterRegistry;import java.time.*;import java.util.UUID;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class NotificationDispatchService{static final String CONSUMER="notification-dispatch-v1";private final NotificationDeliveryRepository deliveries;private final NotificationRepository notifications;private final ProcessedEventStore processed;private final EmailNotificationSender email;private final SmsNotificationSender sms;private final OutboxStore outbox;private final KafkaTopicProperties topics;private final MeterRegistry metrics;private final Clock clock;public NotificationDispatchService(NotificationDeliveryRepository d,NotificationRepository n,ProcessedEventStore p,EmailNotificationSender e,SmsNotificationSender s,OutboxStore o,KafkaTopicProperties t,MeterRegistry m,Clock c){deliveries=d;notifications=n;processed=p;email=e;sms=s;outbox=o;topics=t;metrics=m;clock=c;}
 @Transactional public void dispatch(NotificationDispatchRequestedEvent event){event.metadata().require(EventType.NOTIFICATION_DISPATCH_REQUESTED,1);if(processed.contains(event.metadata(),CONSUMER))return;NotificationDelivery d=deliveries.lockById(event.deliveryId()).orElseThrow(()->new IllegalArgumentException("Notification delivery does not exist"));if(d.getStatus()!=NotificationDeliveryStatus.PENDING){processed.add(event.metadata(),CONSUMER);return;}Notification n=notifications.findById(event.notificationId()).orElseThrow();Instant now=Instant.now(clock);d.processing(now);SendResult result=send(d,n);int retries=0;while(result.result()==SendResult.Result.TEMPORARY_FAILURE&&retries++<2){metrics.counter("notification_dispatch_retry_total","channel",d.getChannel().name()).increment();result=send(d,n);}if(result.result()==SendResult.Result.SUCCESS){d.sent(now);resultEvent(event,d,n,true,null,now);metrics.counter("notification_dispatch_success_total","channel",d.getChannel().name()).increment();}else{d.failed(now,result.failureCode());resultEvent(event,d,n,false,result.failureCode(),now);metrics.counter("notification_dispatch_failure_total","channel",d.getChannel().name()).increment();}processed.add(event.metadata(),CONSUMER);}
 private SendResult send(NotificationDelivery d,Notification n){return d.getChannel()==NotificationChannel.EMAIL?email.send(d.getDestination(),n.getTitle(),n.getMessage()):sms.send(d.getDestination(),n.getMessage());}
 private void resultEvent(NotificationDispatchRequestedEvent cause,NotificationDelivery d,Notification n,boolean ok,String code,Instant now){EventType type=ok?EventType.NOTIFICATION_DELIVERED:EventType.NOTIFICATION_FAILED;EventMetadata m=new EventMetadata(UUID.randomUUID(),type,1,"NOTIFICATION",n.getId(),now,cause.metadata().correlationId(),cause.metadata().eventId(),"notification-service");Object e=ok?new NotificationDeliveredEvent(m,n.getId(),n.getUserId(),d.getChannel().name(),d.getId(),now):new NotificationFailedEvent(m,n.getId(),n.getUserId(),d.getChannel().name(),d.getId(),code,now);outbox.enqueue(topics.notificationEvents(),n.getId(),e,m);}
}
